:- module(m__eu_data_protection_gdpr_data_subject_rights_articles_20_to_22_decision_and_exception_citations, [citation/2, implements/1]).
:- use_module(library(lists)).
:- use_module(library(iso_ext)).
:- use_module(library(between)).
:- use_module(library(dif)).

implements(Key) :-
    citation(Key, _).

citation(eu_reg_2016_679_art_12_2, [label - 'Regulation (EU) 2016/679 (GDPR) Art 12(2), second sentence (refusal where the controller is not in a position to identify the data subject)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504', verbatim - 'unless the controller demonstrates that it is not in a position to identify the data subject']).
citation(eu_reg_2016_679_art_12_5, [label - 'Regulation (EU) 2016/679 (GDPR) Art 12(5), second and third sentences (manifestly unfounded or excessive requests; reasonable fee or refusal)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504', verbatim - 'Where requests from a data subject are manifestly unfounded or excessive, in particular because of their repetitive character, the controller may either']).
citation(eu_reg_2016_679_art_12_6, [label - 'Regulation (EU) 2016/679 (GDPR) Art 12(6) (reasonable doubts concerning identity; additional information to confirm identity)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504', verbatim - 'where the controller has reasonable doubts concerning the identity of the natural person making the request referred to in Articles 15 to 21, the controller may request the provision of additional information necessary to confirm the identity of the data subject']).
citation(eu_reg_2016_679_art_20_1, [label - 'Regulation (EU) 2016/679 (GDPR) Art 20(1), points (a) and (b) (right to data portability: provided data, consent or contract, automated means)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504', verbatim - 'The data subject shall have the right to receive the personal data concerning him or her, which he or she has provided to a controller']).
citation(eu_reg_2016_679_art_20_3, [label - 'Regulation (EU) 2016/679 (GDPR) Art 20(3), second sentence (portability does not apply to processing necessary for a public-interest task or official authority)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504', verbatim - 'That right shall not apply to processing necessary for the performance of a task carried out in the public interest or in the exercise of official authority vested in the controller.']).
citation(eu_reg_2016_679_art_20_4, [label - 'Regulation (EU) 2016/679 (GDPR) Art 20(4) (portability shall not adversely affect the rights and freedoms of others)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504', verbatim - 'The right referred to in paragraph 1 shall not adversely affect the rights and freedoms of others.']).
citation(eu_reg_2016_679_art_21_1, [label - 'Regulation (EU) 2016/679 (GDPR) Art 21(1) (objection to Art 6(1)(e) or (f) processing on particular-situation grounds; compelling legitimate grounds; legal claims)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504', verbatim - 'The controller shall no longer process the personal data unless the controller demonstrates compelling legitimate grounds for the processing which override the interests, rights and freedoms of the data subject or for the establishment, exercise or defence of legal claims.']).
citation(eu_reg_2016_679_art_21_2, [label - 'Regulation (EU) 2016/679 (GDPR) Art 21(2) (right to object to processing for direct marketing)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504', verbatim - 'Where personal data are processed for direct marketing purposes, the data subject shall have the right to object at any time to processing of personal data concerning him or her for such marketing']).
citation(eu_reg_2016_679_art_21_3, [label - 'Regulation (EU) 2016/679 (GDPR) Art 21(3) (no further processing for direct marketing after an objection)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504', verbatim - 'Where the data subject objects to processing for direct marketing purposes, the personal data shall no longer be processed for such purposes.']).
citation(eu_reg_2016_679_art_21_6, [label - 'Regulation (EU) 2016/679 (GDPR) Art 21(6) (objection to Art 89(1) research or statistics processing; public-interest task exception)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504', verbatim - 'shall have the right to object to processing of personal data concerning him or her, unless the processing is necessary for the performance of a task carried out for reasons of public interest']).
citation(eu_reg_2016_679_art_22_1, [label - 'Regulation (EU) 2016/679 (GDPR) Art 22(1) (right not to be subject to a decision based solely on automated processing with legal or similarly significant effects)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504', verbatim - 'The data subject shall have the right not to be subject to a decision based solely on automated processing, including profiling, which produces legal effects concerning him or her or similarly significantly affects him or her.']).
citation(eu_reg_2016_679_art_22_2_a, [label - 'Regulation (EU) 2016/679 (GDPR) Art 22(2)(a) (decision necessary for entering into, or performance of, a contract)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504', verbatim - 'is necessary for entering into, or performance of, a contract between the data subject and a data controller']).
citation(eu_reg_2016_679_art_22_2_b, [label - 'Regulation (EU) 2016/679 (GDPR) Art 22(2)(b) (decision authorised by Union or Member State law laying down suitable safeguards)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504', verbatim - 'is authorised by Union or Member State law to which the controller is subject']).
citation(eu_reg_2016_679_art_22_2_c, [label - 'Regulation (EU) 2016/679 (GDPR) Art 22(2)(c) (decision based on explicit consent)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504', verbatim - 'explicit consent']).
citation(eu_reg_2016_679_art_22_3, [label - 'Regulation (EU) 2016/679 (GDPR) Art 22(3) (minimum safeguards for points (a) and (c) of Art 22(2): human intervention, point of view, contest)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504', verbatim - 'at least the right to obtain human intervention on the part of the controller, to express his or her point of view and to contest the decision']).
citation(eu_reg_2016_679_art_22_4, [label - 'Regulation (EU) 2016/679 (GDPR) Art 22(4) (bar on Art 22(2) decisions based on special categories of personal data)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504', verbatim - 'Decisions referred to in paragraph 2 shall not be based on special categories of personal data referred to in Article 9(1)']).
citation(eu_reg_2016_679_art_23_1, [label - 'Regulation (EU) 2016/679 (GDPR) Art 23(1), opening words (restriction by Union or Member State legislative measure of the rights in Articles 12 to 22)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504', verbatim - 'may restrict by way of a legislative measure the scope of the obligations and rights provided for in Articles 12 to 22']).
